import React, { useEffect, useState } from "react";

function Dashboard() {
  const [resumes, setResumes] = useState([]);
  const [loading, setLoading] = useState(true);

  const token = localStorage.getItem("token");

  // ============================
  // 📥 FETCH RESUMES
  // ============================
  const fetchResumes = async () => {
    try {
      setLoading(true);

      const res = await fetch("http://localhost:5000/api/resume/my", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) throw new Error("Fetch failed");

      const data = await res.json();

      console.log("🔥 FULL DATA:", data);

      setResumes(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error("Fetch error:", err);
      alert("Failed to load resumes");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchResumes();
  }, []);

  // ============================
  // ❌ DELETE
  // ============================
  const handleDelete = async (id) => {
    try {
      await fetch(`http://localhost:5000/api/resume/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      fetchResumes();
    } catch (err) {
      console.error(err);
      alert("Delete failed");
    }
  };

  // ============================
  // ✏️ EDIT
  // ============================
  const handleEdit = async (id, oldText) => {
    const newText = prompt("Edit Resume:", oldText);

    if (!newText || newText.trim() === "") return;

    try {
      await fetch(`http://localhost:5000/api/resume/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ text: newText }),
      });

      fetchResumes();
    } catch (err) {
      console.error(err);
      alert("Update failed");
    }
  };

  // ============================
  // 📄 DOWNLOAD
  // ============================
  const handleDownload = async (text) => {
    try {
      if (!text || text.trim() === "") {
        alert("No resume content");
        return;
      }

      const res = await fetch("http://localhost:5000/api/resume/download", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ text }),
      });

      if (!res.ok) throw new Error();

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = "resume.pdf";
      a.click();

    } catch (err) {
      console.error(err);
      alert("PDF download failed");
    }
  };

  // ============================
  // UI
  // ============================
  return (
    <div style={styles.page}>
      {/* HEADER */}
      <div style={styles.header}>
        <h1 style={styles.logo}>CareerForge Pro 🚀</h1>

        <div style={styles.actions}>
          <button style={styles.primaryBtn} onClick={() => window.location.href = "/"}>
            Analyze Resume
          </button>

          <button
            style={styles.logoutBtn}
            onClick={() => {
              localStorage.removeItem("token");
              window.location.href = "/login";
            }}
          >
            Logout
          </button>
        </div>
      </div>

      <h2 style={styles.title}>Your Saved Resumes</h2>

      {loading ? (
        <p>Loading...</p>
      ) : resumes.length === 0 ? (
        <p style={styles.empty}>No resumes found</p>
      ) : (
        <div style={styles.grid}>
          {resumes.map((r) => (
            <div key={r._id} style={styles.card}>
              
              <div style={styles.cardTop}>
                <span style={styles.score}>
                  ATS: {r.atsScore || 0}
                </span>

                <span style={styles.date}>
                  {r.createdAt
                    ? new Date(r.createdAt).toLocaleString()
                    : "N/A"}
                </span>
              </div>

              {/* 🔥 FIXED CONTENT DISPLAY */}
              <div style={styles.resume}>
                {r.text ? r.text : "No resume content"}
              </div>

              <div style={styles.cardActions}>
                <button
                  style={styles.editBtn}
                  onClick={() => handleEdit(r._id, r.text)}
                >
                  Edit
                </button>

                <button
                  style={styles.deleteBtn}
                  onClick={() => handleDelete(r._id)}
                >
                  Delete
                </button>

                <button
                  style={styles.downloadBtn}
                  onClick={() => handleDownload(r.text)}
                >
                  Download
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ============================
// 🎨 STYLES
// ============================
const styles = {
  page: {
    padding: "20px",
    background: "#0a0e17",
    minHeight: "100vh",
    color: "white",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
  },
  logo: {
    color: "#38bdf8",
  },
  actions: {
    display: "flex",
    gap: "10px",
  },
  primaryBtn: {
    background: "#38bdf8",
    border: "none",
    padding: "8px 14px",
    borderRadius: "6px",
    cursor: "pointer",
  },
  logoutBtn: {
    background: "#ef4444",
    border: "none",
    padding: "8px 14px",
    borderRadius: "6px",
    cursor: "pointer",
    color: "white",
  },
  title: {
    marginTop: "20px",
  },
  empty: {
    opacity: 0.7,
  },
  grid: {
    display: "grid",
    gap: "20px",
    marginTop: "20px",
  },
  card: {
    background: "#0b1220",
    padding: "15px",
    borderRadius: "10px",
    border: "1px solid #1e293b",
  },
  cardTop: {
    display: "flex",
    justifyContent: "space-between",
  },
  score: {
    background: "#22c55e",
    padding: "4px 8px",
    borderRadius: "5px",
    fontSize: "12px",
  },
  date: {
    fontSize: "12px",
    opacity: 0.7,
  },
  resume: {
    marginTop: "10px",
    whiteSpace: "pre-wrap",
    maxHeight: "200px",
    overflow: "auto",
  },
  cardActions: {
    marginTop: "10px",
    display: "flex",
    gap: "10px",
  },
  editBtn: {
    background: "#3b82f6",
    border: "none",
    padding: "6px 10px",
    cursor: "pointer",
    color: "white",
  },
  deleteBtn: {
    background: "#ef4444",
    border: "none",
    padding: "6px 10px",
    cursor: "pointer",
    color: "white",
  },
  downloadBtn: {
    background: "#22c55e",
    border: "none",
    padding: "6px 10px",
    cursor: "pointer",
    color: "white",
  },
};

export default Dashboard;
